/// <summary>
/// The class <c>UPSPricingAttributeSourceDiscoveryAttribute</c> is used for tagging <c>PricingAttributeSource</c>.
/// </summary>
public class UPSPricingAttributeSourceDiscoveryAttribute extends SysAttribute implements SysExtensionIAttribute
{
    public UPSPricingAttributeSourceLevel level;
    public UPSPricingAttributeSource source;

}

Method.Source:
public void new(UPSPricingAttributeSource _source, UPSPricingAttributeSourceLevel _level)
{
    this.level = _level;
    this.source = _source;
}
